predicate isRemoteRequestSource(DataFlow::Node source) {
  exists(Express::RouteHandler rh | source = rh.getARequest())
}

predicate isRemoteFlowSource(DataFlow::Node source) {
  exists(RemoteFlowSource remote | source = remote)
}

predicate isEvalSink(DataFlow::Node sink) {
  exists(DataFlow::CallNode call | call = DataFlow::globalVarRef("eval").getACall() and sink = call.getArgument(0))
}

predicate isStatementExecuteSink(DataFlow::Node sink) {
  exists(MethodCall call | call.getMethod().hasName("execute") and sink.asExpr() = call.getArgument(0))
}
